using System;
using System.Collections.Generic;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Http;

namespace PaymentGateway.Controllers
{
    public enum CircuitState { Closed, Open, HalfOpen }

    public class CircuitBreaker
    {
        private CircuitState _state = CircuitState.Closed;
        private int _failureCount = 0;
        private readonly int _threshold = 5;
        private DateTime _lastFailureTime = DateTime.MinValue;
        private readonly TimeSpan _recoveryTimeout = TimeSpan.FromSeconds(30);
        private readonly object _lock = new object();

        public CircuitState State
        {
            get
            {
                lock (_lock)
                {
                    if (_state == CircuitState.Open &&
                        DateTime.UtcNow - _lastFailureTime >= _recoveryTimeout)
                    {
                        _state = CircuitState.HalfOpen;
                    }
                    return _state;
                }
            }
        }

        public void RecordSuccess()
        {
            lock (_lock)
            {
                _failureCount = 0;
                _state = CircuitState.Closed;
            }
        }

        public void RecordFailure()
        {
            lock (_lock)
            {
                _failureCount++;
                _lastFailureTime = DateTime.UtcNow;
                if (_failureCount >= _threshold)
                    _state = CircuitState.Open;
            }
        }
    }

    public class OAuthConfig
    {
        public string ClientId { get; set; } = "payment-gateway-prod";
        public string AuthorizationEndpoint { get; set; } = "https://auth.paymentprovider.com/authorize";
        public string TokenEndpoint { get; set; } = "https://auth.paymentprovider.com/token";
        public List<string> AllowedRedirectDomains { get; set; } = new List<string>
        {
            "payments.example.com",
            "checkout.example.com",
            "api.example.com"
        };
    }

    [ApiController]
    [Route("api/[controller]")]
    public class PaymentAuthController : ControllerBase
    {
        private static readonly CircuitBreaker _circuitBreaker = new CircuitBreaker();
        private static readonly OAuthConfig _config = new OAuthConfig();
        private static readonly Dictionary<string, string> _stateStore = new Dictionary<string, string>();

        [HttpGet("initiate")]
        public IActionResult InitiatePaymentAuth([FromQuery] string returnUrl, [FromQuery] decimal amount)
        {
            if (_circuitBreaker.State == CircuitState.Open)
            {
                return StatusCode(503, new { error = "Payment service temporarily unavailable" });
            }

            if (string.IsNullOrEmpty(returnUrl))
                return BadRequest(new { error = "returnUrl is required" });

            if (!ValidateRedirectUri(returnUrl))
                return BadRequest(new { error = "Invalid redirect URI" });

            var state = GenerateSecureState();
            _stateStore[state] = returnUrl;

            var authUrl = BuildAuthorizationUrl(state, amount);
            return Redirect(authUrl);
        }

        [HttpGet("callback")]
        public async Task<IActionResult> OAuthCallback([FromQuery] string code, [FromQuery] string state)
        {
            if (string.IsNullOrEmpty(state) || !_stateStore.ContainsKey(state))
            {
                _circuitBreaker.RecordFailure();
                return BadRequest(new { error = "Invalid state parameter" });
            }

            var returnUrl = _stateStore[state];
            _stateStore.Remove(state);

            try
            {
                var tokenResult = await ExchangeCodeForToken(code);
                if (tokenResult == null)
                {
                    _circuitBreaker.RecordFailure();
                    return StatusCode(502, new { error = "Token exchange failed" });
                }

                _circuitBreaker.RecordSuccess();
                var separator = returnUrl.Contains("?") ? "&" : "?";
                return Redirect($"{returnUrl}{separator}token={tokenResult}&status=success");
            }
            catch (Exception)
            {
                _circuitBreaker.RecordFailure();
                if (_circuitBreaker.State == CircuitState.HalfOpen)
                {
                    return Redirect($"{returnUrl}?status=retry");
                }
                return StatusCode(500, new { error = "Payment processing failed" });
            }
        }

        private bool ValidateRedirectUri(string uri)
        {
            if (!Uri.TryCreate(uri, UriKind.Absolute, out var parsedUri))
                return false;

            if (parsedUri.Scheme != "https")
                return false;

            var host = parsedUri.Host;
            return _config.AllowedRedirectDomains.Any(domain =>
                host.EndsWith(domain, StringComparison.OrdinalIgnoreCase));
        }

        private string BuildAuthorizationUrl(string state, decimal amount)
        {
            var redirectUri = Uri.EscapeDataString("https://api.example.com/api/PaymentAuth/callback");
            return $"{_config.AuthorizationEndpoint}?client_id={_config.ClientId}" +
                   $"&redirect_uri={redirectUri}&state={state}&amount={amount}" +
                   $"&response_type=code&scope=payment";
        }

        private string GenerateSecureState()
        {
            var bytes = new byte[32];
            using (var rng = RandomNumberGenerator.Create())
            {
                rng.GetBytes(bytes);
            }
            return Convert.ToBase64String(bytes).Replace("+", "-").Replace("/", "_").TrimEnd('=');
        }

        private async Task<string> ExchangeCodeForToken(string code)
        {
            await Task.Delay(100); // Simulated HTTP call
            if (string.IsNullOrEmpty(code)) return null;
            return Convert.ToBase64String(Encoding.UTF8.GetBytes($"token_{code}_{DateTime.UtcNow.Ticks}"));
        }
    }
}
